import {styles,styleOf,ruleFor} from './styles.js';
import {rulesMarkup,bindRules} from './rule-ui.js';
import {styleArt,demoProject} from './presets.js';
import {fresh,storyboardData,parseCode,words,norm,sameNarration,invalidate,total,locate,align,globalCues,sourceOf,srt,validateProject,jsonText} from './model.js';
import * as storage from './storage.js';
import * as cloud from './cloud.js';
import {storyboardPrompt,animationPrompt,repairPrompt,alignmentPrompt} from './prompts.js';
import {syntax} from './validation.js';
import {decode,wav16k,base64,unbase64,effect} from './audio.js';
import {exportVideo,support} from './exporter.js';
import {zipSync,unzipSync,strToU8} from './vendor/fflate.js';
const $=s=>document.querySelector(s),esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let p=fresh(),tab=0,selected=0,position=0,worker,signature='',pending,playing=false,playToken=0,clock,voiceBuffer,musicBuffer,saveTimer,toastTimer,exporting=false,cancelExport=false,apiKey='',mediaUrl,workerEpoch=0;
let localMode=[0,1,0,0,1];
const names=['Ide','Narasi','Suara','Animasi','Ekspor'],canvas=$('#screen'),context=canvas.getContext('2d'),dialog=$('#dialog');
const seconds=n=>Number(n).toFixed(2)+' dtk';
function notify(message){$('#notice').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#notice').textContent='',5000);}
async function persist(){clearTimeout(saveTimer);try{await storage.save(p);localStorage.setItem('ruang-active',p.id);$('#saved').textContent='Tersimpan di perangkat ini';}catch(e){$('#saved').textContent='Belum tersimpan';notify('Penyimpanan perangkat gagal. Unduh cadangan proyek.');}}
function changed(){p.updated=Date.now();$('#saved').textContent='Menyimpan…';clearTimeout(saveTimer);saveTimer=setTimeout(persist,400);}
function button(id,fn){const el=$('#'+id);if(el)el.onclick=()=>Promise.resolve().then(fn).catch(showError);}
function showError(e){if(dialog.open)$('#dialog-error').textContent=e.message||e;else notify(e.message||e);}
function openDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#dialog-error').textContent='';if(!dialog.open)dialog.showModal();}
$('#closeDialog').onclick=()=>{if(exporting){cancelExport=true;return;}dialog.close();};dialog.addEventListener('cancel',e=>{if(exporting){e.preventDefault();cancelExport=true;}});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function copy(text){try{await navigator.clipboard.writeText(text);notify('Prompt disalin. Tempel di AI pilihan Anda.');}catch{throw Error('Browser menolak akses clipboard. Gunakan Lihat prompt untuk menyalin secara manual.');}}
let latestPrompt;
function promptDialog(title,text){latestPrompt={title,text};return copy(text).catch(showError);}
function viewPrompt(){if(!latestPrompt)throw Error('Siapkan prompt melalui tombol Salin prompt terlebih dahulu.');const {title,text}=latestPrompt;openDialog(title,'<label for="prompt">Prompt lengkap</label><textarea class="code" id="prompt" readonly>'+esc(text)+'</textarea><div class="row"><button class="primary" id="copyPrompt">Salin prompt</button><button id="downloadPrompt">Unduh .md</button></div>');button('copyPrompt',()=>copy(text));button('downloadPrompt',()=>download(new Blob([text],{type:'text/markdown'}),'prompt-reka-studio.md'));}
function stopWorker(){workerEpoch++;worker?.terminate();worker=null;signature='';if(pending){clearTimeout(pending.timer);pending.reject(Error('Pratinjau diganti.'));pending=null;}}
function send(message){return new Promise((resolve,reject)=>{if(pending)return reject(Error('Render masih berjalan.'));const timer=setTimeout(()=>{pending=null;worker?.terminate();worker=null;signature='';reject(Error('Kode berhenti merespons setelah 4 detik. Periksa loop pada scene.'));},4000);pending={resolve,reject,timer};worker.postMessage(message);});}
async function draw(index,t,width=360,height=640){const scene=p.scenes[index];if(!scene?.code?.trim())return[];const key=JSON.stringify([p.world,scene,p.aspect,p.subtitle,p.background,(p.assets||[]).map(a=>[a.id,a.name,a.blob?.size]),width,height]);if(signature!==key){stopWorker();syntax(p.world,scene.code,scene.id);worker=new Worker('render-worker.js');worker.onmessage=e=>{const q=pending;pending=null;if(!q){e.data.bitmap?.close();return;}clearTimeout(q.timer);e.data.error?q.reject(Error(e.data.error)):q.resolve(e.data);};worker.onerror=e=>{if(pending){clearTimeout(pending.timer);pending.reject(Error(e.message));pending=null;}stopWorker();};await send({type:'init',world:p.world,scene,aspect:p.aspect,subtitle:p.subtitle,background:p.background,assets:p.assets||[],width,height});signature=key;}const r=await send({type:'frame',t});if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}context.drawImage(r.bitmap,0,0);r.bitmap.close();return r.sounds;}
function previewSize(){return p.aspect==='16:9'?[640,360]:[360,640];}
async function preview(){if(playing||exporting)return;$('#preview-error').textContent='';$('#repairPreview').hidden=true;const row=p.scenes[selected];$('#empty').hidden=!!row?.code;$('#play').disabled=!row?.code;$('#scrub').disabled=!row?.code;$('#scrub').max=row?.duration||1;$('#scrub').value=position;$('#time').textContent=`${position.toFixed(2)} / ${(row?.duration||0).toFixed(2)}`;$('.screen-wrap').style.aspectRatio=p.aspect==='16:9'?'16/9':'9/16';if(!row?.code){context.clearRect(0,0,canvas.width,canvas.height);return;}try{await draw(selected,Math.min(position,row.duration),...previewSize());}catch(e){if(e.message!=='Pratinjau diganti.'){$('#preview-error').textContent=e.message;$('#repairPreview').hidden=false;}}}
function pause(){playing=false;playToken++;$('#play').textContent='Putar';if(clock){clock.close();clock=null;}}
async function play(){
  if(playing){pause();return;}if(exporting)return;
  const all=$('#all').checked;
  if(all&&p.scenes.some(s=>!s.code.trim()))throw Error('Lengkapi kode semua scene sebelum memutar seluruh video.');
  const row=p.scenes[selected];if(!row?.code)return;
  pause();const token=++playToken;playing=true;$('#play').textContent='Jeda';
  const startOffset=p.scenes.slice(0,selected).reduce((v,s)=>v+s.duration,0);
  if(position>=row.duration-.02)position=0;
  const origin=startOffset+position,limit=all?total(p):startOffset+row.duration;
  clock=new AudioContext();const ac=clock,scheduled=new Set();await ac.resume();
  try{
    if(p.audio)voiceBuffer??=await decode(p.audio.blob);
    if(p.music)musicBuffer??=await decode(p.music.blob);
    if(token!==playToken)return;
    await draw(selected,position,...previewSize());
    if(token!==playToken)return;
    const epoch=ac.currentTime+.05;
    for(const [buffer,gain,loop]of[[voiceBuffer,1,false],[musicBuffer,p.volume,true]]){
      if(!buffer)continue;
      const source=ac.createBufferSource(),volume=ac.createGain();source.buffer=buffer;source.loop=loop;volume.gain.value=gain;source.connect(volume);volume.connect(ac.destination);
      const offset=loop?origin%buffer.duration:origin;if(offset<buffer.duration)source.start(epoch,offset);
    }
    const frame=async()=>{
      if(token!==playToken||!playing)return;
      const absolute=Math.min(limit,origin+Math.max(0,ac.currentTime-epoch)),pos=locate(p,Math.min(absolute,limit-.000001));
      const sceneChanged=selected!==pos.index;selected=pos.index;position=pos.local;
      try{
        const sounds=await draw(selected,position,...previewSize());if(token!==playToken)return;
        if(p.sfx)for(const e of sounds){const key=selected+':'+e.name+':'+e.time,at=pos.start+e.time;if(!scheduled.has(key)&&at>=origin&&at<limit&&epoch+at-origin>=ac.currentTime-.04&&e.time<p.scenes[selected].duration){effect(ac,ac.destination,e,Math.max(ac.currentTime,epoch+at-origin));scheduled.add(key);}}
        $('#time').textContent=`${(all?absolute:position).toFixed(2)} / ${(all?total(p):row.duration).toFixed(2)}`;
        $('#scrub').max=p.scenes[selected].duration;$('#scrub').value=position;if(sceneChanged)updateSceneButtons();
        if(absolute>=limit){pause();return;}requestAnimationFrame(frame);
      }catch(e){if(token===playToken){pause();$('#preview-error').textContent=e.message;$('#repairPreview').hidden=false;}}
    };frame();
  }catch(e){if(token===playToken)pause();throw e;}
}
button('play',play);$('#scrub').oninput=()=>{pause();position=Number($('#scrub').value);preview();};$('#all').onchange=()=>{pause();preview();};
function updateSceneButtons(){$('#scene-list').innerHTML=p.scenes.map((r,i)=>`<button class="${i===selected?'active ':''}${r.code?'ready ':''}${r.reviewReason?'stale':''}" aria-label="Scene ${r.id}${r.code?', kode tersedia':''}" data-scene="${i}">${r.id}</button>`).join('');$('#scene-list').querySelectorAll('button').forEach(b=>b.onclick=()=>{pause();selected=Number(b.dataset.scene);position=0;render();});$('#scene-status').textContent=p.scenes.length?`Scene ${p.scenes[selected]?.id} · ${p.scenes.length} adegan`:'Belum ada scene';}
function render(){
 if(exporting)return;const stage=Math.min(tab,3),pane=tab===4?2:localMode[tab];document.body.dataset.stage=String(stage);document.body.dataset.pane=String(pane);
 $('#stage-label').textContent='0'+(stage+1)+' / '+names[stage].toUpperCase();$('#projectTitle').value=p.title;
 $('#tabs').innerHTML=names.slice(0,4).map((n,i)=>`<button data-tab="${i}" ${stage===i?'aria-current="step"':''}><span class="num">0${i+1}</span>${n}</button>`).join('');
 $('#tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{pause();tab=Number(b.dataset.tab);setView('editor');render();window.scrollTo(0,0);});
 const labels=[['Atur','Pilih ide'],['Atur','Naskah'],['Atur','Sinkron'],['Atur','Preview','Ekspor MP4']][stage];
 $('#subtabs').innerHTML=labels.map((n,i)=>`<button data-pane="${i}" ${pane===i?'aria-current="page"':''}>${n}</button>`).join('');
 $('#subtabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{pause();if(stage===3&&Number(b.dataset.pane)===2){tab=4;}else{tab=stage;localMode[stage]=Number(b.dataset.pane);}setView(stage===3&&Number(b.dataset.pane)===1?'monitor':'editor');render();window.scrollTo(0,0);});
 if(tab===4)exportPanel();else if(tab===0&&pane===1)ideaResults();else if(tab===1&&pane===0)storySettings();else if(tab===3&&pane===1)previewPanel();else [idea,narration,sound,scene][tab]();
 if(pane===0){const key=['idea','story','voice','animation'][stage];$('#editor').insertAdjacentHTML('beforeend',rulesMarkup(p,key,esc));bindRules(p,key,changed,notify,render);}
 if(tab===2)configureVoicePane(pane);if(tab===0&&pane===0)mountGallery();if(tab===3&&pane===0){mountQueue();mountAssets();}
 mountFlowEnhancements();updateSceneButtons();preview();
}
function storySettings(){$('#editor').innerHTML=`<h1>Aturan storyboard</h1><p class="intro">Gaya, aset dan naskah final menjadi acuan semua scene.</p><div class="selected-style"><strong>${esc(styleOf(p).name)}</strong><p>${esc(styleOf(p).description)}</p></div><p class="note">${words(p.narration).length} kata · naskah asli dikunci</p><div class="row"><button class="primary" id="storySettingsPrompt">Salin prompt storyboard</button><button id="storySettingsPaste">Tempel jawaban AI</button></div>`;button('storySettingsPrompt',()=>promptDialog('Prompt storyboard',storyboardPrompt(p)));button('storySettingsPaste',()=>{tab=0;localMode[0]=0;render();$('#pasteStory').click();});}
function previewPanel(){$('#editor').innerHTML=`<h1>Preview video</h1><p class="intro">Tinjau bentuk, gerak dan sambungan antar-scene. VO dan subtitle mengikuti timeline proyek.</p><p>${p.scenes.filter(s=>s.code).length} / ${p.scenes.length} scene memiliki kode · ${seconds(total(p))}</p><div class="row"><button id="openExport" class="primary">Ekspor MP4</button><button id="returnAnimation">Kembali ke Atur</button></div>`;button('openExport',()=>{tab=4;setView('editor');render();});button('returnAnimation',()=>{tab=3;localMode[3]=0;setView('editor');render();});}
function ideaResults(){const list=p.ideaCandidates||[];$('#editor').innerHTML=`<h1>Pilih sudut ceritanya</h1><p class="intro">Untuk naskah yang sudah jadi, langsung gunakan prompt storyboard di Atur. Jika masih mencari ide, gunakan langkah di bawah.</p><label for="ideaTopic">Topik ide</label><input id="ideaTopic" value="${esc(p.ideaTopic||'')}" placeholder="Contoh: benda sehari-hari"><div class="row"><button id="ideasPrompt" class="primary">Salin prompt ide</button><button id="ideasPaste">Tempel daftar ide</button></div>${list.map((v,i)=>`<article class="idea-option"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(v.title)}</h3><p>${esc(v.angle||'')}</p><button data-idea="${i}">Pakai judul ini</button></div></article>`).join('')}`;$('#ideaTopic').oninput=e=>{p.ideaTopic=e.target.value;changed();};button('ideasPrompt',()=>promptDialog('Prompt ide',`Buat 10 ide video bahasa Indonesia tentang ${p.ideaTopic||'mekanisme sehari-hari'}. Gaya ${styleOf(p).name}. Judul menarik dan jujur, sudut cerita konkret. Jangan menulis naskah atau mengubah naskah yang sudah ada. Jawab satu blok JSON {"ideas":[{"title":"judul","angle":"sudut penjelasan"}]}.\nAturan: ${ruleFor(p,'idea')}\n=== AKHIR PERINTAH ===`));button('ideasPaste',()=>{openDialog('Tempel daftar ide','<label for="ideasJson">JSON ide</label><textarea id="ideasJson" class="code"></textarea><button id="applyIdeas" class="primary">Gunakan daftar</button>');button('applyIdeas',()=>{const v=JSON.parse(jsonText($('#ideasJson').value)).ideas;if(!Array.isArray(v)||!v.length||v.some(x=>typeof x.title!=='string'))throw Error('Gunakan JSON berisi ideas dengan title.');p.ideaCandidates=v.slice(0,30);changed();dialog.close();render();});});document.querySelectorAll('[data-idea]').forEach(b=>b.onclick=()=>{p.title=list[Number(b.dataset.idea)].title;changed();localMode[0]=0;render();notify('Judul dipilih. Masukkan naskah final Anda di Atur.');});}

function idea(){$('#editor').innerHTML=`<p class="eyebrow">MEJA SUNTING / NASKAH</p><h1>Naskah & arahan visual</h1><p class="intro">Masukkan naskah final Anda. Siapkan prompt, salin ke AI, lalu tempel storyboard-nya di sini.</p><label for="narration">Narasi final</label><textarea class="narration" id="narration" placeholder="Kok kita bisa bernapas di pesawat, padahal udara di luar begitu tipis?">${esc(p.narration)}</textarea><p class="note" id="wordCount">${words(p.narration).length} kata · naskah tidak ditulis ulang otomatis</p><div class="two"><div><label for="style">Arahan tambahan</label><input id="style" value="${esc(p.styleNotes||'')}"></div><div><label for="aspect">Format</label><select id="aspect"><option ${p.aspect==='9:16'?'selected':''}>9:16</option><option ${p.aspect==='16:9'?'selected':''}>16:9</option></select></div></div><div class="step-instruction"><b>↗</b><span>Salin prompt ke AI pilihan Anda. Setelah mendapat jawaban, kembali dan tempel JSON storyboard.</span></div><div class="row"><button class="primary" id="storyPrompt">1. Salin prompt storyboard</button><button id="pasteStory">2. Tempel jawaban AI</button></div>${p.scenes.length?'<p class="note">Mengganti naskah akan meminta storyboard baru. Cadangan kode lama tetap dapat diunduh lewat Proyek & berkas.</p>':''}`;$('#narration').oninput=e=>{p.narration=e.target.value;invalidate(p,'Naskah berubah; buat ulang storyboard.');$('#wordCount').textContent=words(p.narration).length+' kata · naskah tidak ditulis ulang otomatis';changed();};$('#style').oninput=e=>{p.styleNotes=e.target.value;invalidate(p,'Arahan visual berubah.');changed();};$('#aspect').onchange=e=>{p.aspect=e.target.value;invalidate(p,'Format layar berubah.');changed();preview();};button('storyPrompt',()=>{if(!p.narration.trim())throw Error('Masukkan naskah terlebih dahulu.');promptDialog('Prompt storyboard',storyboardPrompt(p));});button('pasteStory',()=>{if(!p.narration.trim())throw Error('Masukkan naskah terlebih dahulu.');openDialog('Tempel storyboard','<p>Tempel JSON dari AI. Semua kata narasi harus tetap sama dan berurutan.</p><label for="storyInput">Hasil AI</label><textarea id="storyInput" class="code" placeholder=\'{"scenes":[...]}\'></textarea><div class="row"><button id="checkStory">Periksa JSON</button><button id="applyStory" class="primary" disabled>Gunakan storyboard</button></div><p id="storyCheck" role="status"></p><div></div>');$('#storyInput').oninput=()=>{$('#applyStory').disabled=true;$('#storyCheck').textContent='';};button('checkStory',()=>{const raw=$('#storyInput').value;const data=storyboardData(raw,p.narration);$('#storyCheck').textContent=data.scenes.length+' scene valid. Naskah cocok persis. '+(/&#(?:91|93|x5b|x5d);|\\_/i.test(raw)?'Format salinan HTML/Markdown dibersihkan. ':'')+'Penekanan disesuaikan dengan tanda baca kata. Storyboard lama dicadangkan saat diterapkan.';$('#applyStory').disabled=false;});button('applyStory',async()=>{const data=storyboardData($('#storyInput').value,p.narration),rows=data.scenes;if(p.scenes.length){const backup={...p,id:crypto.randomUUID(),title:p.title+' · sebelum storyboard baru'};await storage.save(backup);}if(!data.title)delete data.title;Object.assign(p,data);p.scenes=rows;p.world='';selected=0;position=0;tab=1;localMode[1]=1;changed();dialog.close();render();});});}
function narration(){if(!p.scenes.length){$('#editor').innerHTML='<h1>Storyboard belum ada.</h1><p class="intro">Siapkan prompt dari naskah di tab Ide, lalu tempel hasil AI.</p><button id="backIdea" class="primary">Buka Ide</button>';button('backIdea',()=>{tab=0;render();});return;}$('#editor').innerHTML=`<h1>Naskah & storyboard</h1><p class="intro">Narasi tetap utuh. Periksa visual dan durasi setiap scene sebelum menyelaraskan VO.</p><div class="row"><button id="storyPromptAgain">Salin prompt storyboard</button><button id="replaceStoryboard">Tempel storyboard baru</button></div><p class="note">${p.scenes.length} scene · ${seconds(total(p))} · waktu ${p.scenes.every(s=>s.cues.length)?'mengikuti VO':'masih perkiraan'}</p>${p.scenes.map((r,i)=>`<article class="scene-row"><div class="number">${String(r.id).padStart(2,'0')}</div><div><p>${esc(r.text)}</p><label for="visual-${i}">Visual</label><textarea id="visual-${i}" data-visual="${i}">${esc(r.visual)}</textarea><label for="emphasis-${i}">Kata penekanan</label><input id="emphasis-${i}" data-emphasis="${i}" value="${esc(r.emphasis)}"><label for="camera-${i}">Kamera awal → akhir</label><input id="camera-${i}" data-camera="${i}" value="${esc(r.camera)}"><label for="startState-${i}">Keadaan awal</label><input id="startState-${i}" data-startState="${i}" value="${esc(r.startState)}"><label for="endState-${i}">Keadaan akhir</label><input id="endState-${i}" data-endState="${i}" value="${esc(r.endState)}"></div><div><label for="duration-${i}">Detik</label><input id="duration-${i}" type="number" min=".1" max="180" step=".01" data-duration="${i}" value="${r.duration.toFixed(2)}"><label for="theme-${i}">Tema</label><select id="theme-${i}" data-theme="${i}">${['paper','night','dusk'].map(v=>`<option ${v===r.theme?'selected':''}>${v}</option>`).join('')}</select></div></article>`).join('')}${p.storyNotes?.length?`<p class="status-note warning">${p.storyNotes.map(esc).join(" · ")}</p>`:""}<details><summary>Metadata unggahan YouTube</summary><div class="metadata-grid">${["title","description","short","tags","hashtags"].map(k=>`<label for="seo-${k}">${k}</label><textarea id="seo-${k}" data-seo="${k}">${esc(Array.isArray(p.seo?.[k])?p.seo[k].join(", "):p.seo?.[k]||"")}</textarea>`).join("")}</div></details><div class="row"><button class="primary" id="toVoice">Lanjut ke suara</button></div>`;for(const key of ['visual','camera','theme','emphasis','startState','endState'])document.querySelectorAll(`[data-${key}]`).forEach(el=>el.onchange=()=>{p.scenes[Number(el.dataset[key])][key]=el.value;invalidate(p,'Visual atau kamera storyboard berubah.',Number(el.dataset[key]));changed();preview();});document.querySelectorAll('[data-duration]').forEach(el=>el.onchange=()=>{const v=Number(el.value);if(v<.1||v>180||!Number.isFinite(v)){notify('Durasi harus 0,1–180 detik.');render();return;}invalidate(p,'Durasi scene berubah.');p.scenes[Number(el.dataset.duration)].duration=v;for(const r of p.scenes){r.cues=[];r.timing='perkiraan';}changed();render();notify('Durasi berubah. Sinkronkan ulang timing kata.');});button('storyPromptAgain',()=>promptDialog('Prompt storyboard',storyboardPrompt(p)));button('replaceStoryboard',()=>{tab=0;render();$('#pasteStory').click();});document.querySelectorAll('[data-seo]').forEach(el=>el.onchange=()=>{p.seo??={};const k=el.dataset.seo;p.seo[k]=['tags','hashtags'].includes(k)?el.value.split(',').map(v=>v.trim()).filter(Boolean):el.value;changed();});button('toVoice',()=>{tab=2;localMode[2]=0;render();});}
function sound(){$('#editor').innerHTML=`<h1>Voiceover & timing</h1><p class="intro">Unggah VO Anda, lalu cocokkan kata dan subtitle dengan rekamannya. Naskah tidak diganti.</p><label for="voiceFile">Voiceover · MP3, WAV, M4A, atau audio lain yang didukung browser</label><input id="voiceFile" type="file" accept="audio/*">${p.audio?`<p>${esc(p.audio.name)} <span class="note">${seconds(p.audio.duration)}</span></p><canvas id="wave" class="wave" width="900" height="100" aria-label="Bentuk gelombang VO"></canvas><audio id="voicePlayer" controls></audio><div class="row"><button id="sync" class="primary" ${!p.scenes.length?'disabled':''}>Sinkronkan otomatis</button><button id="alignPrompt" ${!p.scenes.length?'disabled':''}>Salin prompt timing</button><button id="timing" ${!p.scenes.length?'disabled':''}>Tinjau / tempel timing</button><button id="removeVoice">Hapus VO</button></div><p class="note">${p.scenes.every(s=>s.timing==='ditinjau')?'Timing sudah ditandai selesai ditinjau.':p.scenes.some(s=>s.cues.length)?'Timing tersedia. Dengarkan dan tinjau sebelum ekspor.':'Belum tersinkron. Waktu subtitle masih perkiraan.'}</p>`:'<p class="note">Maksimal 100 MB. Sinkronisasi berjalan di perangkat tanpa API key. Model diunduh sekali saat pertama digunakan.</p>'}<label for="musicFile">Musik latar opsional</label><input id="musicFile" type="file" accept="audio/*">${p.music?`<p>${esc(p.music.name)}</p><label for="musicVolume">Volume musik: <span id="volumeValue">${Math.round(p.volume*100)}%</span></label><input id="musicVolume" type="range" min="0" max=".5" step=".01" value="${p.volume}"><button id="removeMusic">Hapus musik</button>`:''}<div class="row"><label><input id="subtitles" type="checkbox" ${p.subtitle?'checked':''}> Subtitle</label><label><input id="sfx" type="checkbox" ${p.sfx?'checked':''}> Efek suara dari kode scene</label></div><p class="note">Efek suara disintesis oleh engine. VO tidak dibuat ulang.</p>`;$('#voiceFile').onchange=e=>uploadAudio(e.target.files[0],'audio').catch(showError);$('#musicFile').onchange=e=>uploadAudio(e.target.files[0],'music').catch(showError);$('#subtitles').onchange=e=>{p.subtitle=e.target.checked;changed();preview();};$('#sfx').onchange=e=>{p.sfx=e.target.checked;changed();};button('removeVoice',()=>{p.audio=null;voiceBuffer=null;invalidate(p,'VO dihapus; tinjau timing scene.');for(const r of p.scenes){r.cues=[];r.timing='perkiraan';}changed();render();});button('removeMusic',()=>{p.music=null;musicBuffer=null;changed();render();});if(p.music)$('#musicVolume').oninput=e=>{p.volume=Number(e.target.value);$('#volumeValue').textContent=Math.round(p.volume*100)+'%';changed();};if(p.audio){if(mediaUrl)URL.revokeObjectURL(mediaUrl);mediaUrl=URL.createObjectURL(p.audio.blob);$('#voicePlayer').src=mediaUrl;waveform();}button('alignPrompt',()=>promptDialog('Prompt timing VO',alignmentPrompt(p)+'\n\nLampirkan juga file VO Anda pada pesan ke AI.'));button('sync',syncDialog);button('timing',()=>timingDialog());}
async function uploadAudio(file,key){if(!file)return;if(file.size>100*1024*1024)throw Error('Audio melebihi 100 MB.');notify('Membaca audio…');const buffer=await decode(file);if(buffer.duration>1800)throw Error('Batas durasi audio 30 menit.');p[key]={name:file.name,type:file.type,blob:file,duration:buffer.duration};if(key==='audio'){voiceBuffer=buffer;invalidate(p,'VO diganti; sinkronkan ulang.');for(const row of p.scenes){row.cues=[];row.timing='perkiraan';}}else musicBuffer=buffer;if(key==='audio')localMode[2]=1;await persist();render();notify('Audio siap.');if(key==='audio'&&p.scenes.length)await syncDialog();}
async function waveform(){try{voiceBuffer??=await decode(p.audio.blob);const c=$('#wave');if(!c)return;const ctx=c.getContext('2d'),a=voiceBuffer.getChannelData(0),stride=Math.max(1,Math.floor(a.length/c.width));ctx.clearRect(0,0,c.width,c.height);ctx.strokeStyle='#24684f';ctx.lineWidth=1;ctx.beginPath();for(let x=0;x<c.width;x++){let peak=0;for(let j=x*stride;j<Math.min(a.length,(x+1)*stride);j+=Math.max(1,Math.floor(stride/70)))peak=Math.max(peak,Math.abs(a[j]));ctx.moveTo(x,50-peak*45);ctx.lineTo(x,50+peak*45);}ctx.stroke();}catch(e){notify(e.message);}}
function timingDialog(raw){
 if(!p.audio)throw Error('Unggah VO terlebih dahulu.');
 const cues=globalCues(p),review=new Set(p.alignmentReview||[]);let timingUrl=URL.createObjectURL(p.audio.blob);
 openDialog('Tinjau timing kata','<p>Ketuk kata untuk mendengarkan posisinya. Waktu dihitung dari awal VO dalam detik. Kata bertanda Perkiraan perlu diperiksa.</p><audio id="timingPlayer" controls></audio><div id="timingRows">'+cues.map((c,i)=>'<div class="timing-word"><button data-listen="'+i+'">'+esc(c.word)+(review.has(i)?'<small> · Perkiraan</small>':'')+'</button><label>Mulai<input aria-label="Mulai kata '+(i+1)+'" data-start="'+i+'" type="number" min="0" step=".01" value="'+c.start.toFixed(3)+'"></label><label>Selesai<input aria-label="Selesai kata '+(i+1)+'" data-end="'+i+'" type="number" min="0" step=".01" value="'+c.end.toFixed(3)+'"></label></div>').join('')+'</div><details '+(!cues.length?'open':'')+'><summary>Tempel / edit JSON timing</summary><label for="timingJson">Timestamp kata</label><textarea id="timingJson" class="code">'+esc(raw??JSON.stringify({words:cues},null,2))+'</textarea><button id="applyTimingJson">Terapkan JSON</button></details><div class="row"><button id="applyTiming" class="primary" '+(!cues.length?'disabled':'')+'>Simpan koreksi</button><button id="reviewed" '+(!cues.length?'disabled':'')+'>Selesai ditinjau</button></div>');
 $('#timingPlayer').src=timingUrl;dialog.addEventListener('close',()=>URL.revokeObjectURL(timingUrl),{once:true});
 document.querySelectorAll('[data-listen]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.listen);$('#timingPlayer').currentTime=Math.max(0,Number($('[data-start="'+i+'"]').value)-.12);$('#timingPlayer').play().catch(showError);});
 const edited=()=>cues.map((c,i)=>({...c,start:Number($('[data-start="'+i+'"]').value),end:Number($('[data-end="'+i+'"]').value)}));
 const apply=(data,reviewed=false)=>{p.scenes=align(p,data,p.audio.duration);if(reviewed){p.scenes.forEach(s=>s.timing='ditinjau');p.alignmentReview=[];}changed();dialog.close();render();};
 button('applyTiming',()=>apply(edited()));button('reviewed',()=>apply(edited(),true));button('applyTimingJson',()=>apply(JSON.parse(jsonText($('#timingJson').value))));
}
let syncWorker=null;
function cancelSync(){syncWorker?.terminate();syncWorker=null;}
async function syncDialog(){
 if(!p.audio||!p.scenes.length)throw Error('Siapkan storyboard dan unggah VO terlebih dahulu.');
 cancelSync();openDialog('Sinkronisasi di perangkat','<p>VO diproses di perangkat tanpa API key. Model suara diunduh pada penggunaan pertama dan disimpan oleh browser jika tersedia.</p><div class="sync-state"><p id="syncState" role="status">Menyiapkan audio…</p><progress id="syncProgress" aria-label="Sinkronisasi berlangsung"></progress></div><button id="cancelSync">Batalkan sinkronisasi</button>');
 button('cancelSync',()=>{cancelSync();dialog.close();notify('Sinkronisasi dibatalkan. Timing sebelumnya dipertahankan.');});
 const project=p,audio=p.audio,script=p.scenes.map(s=>s.text).join(' ');
 voiceBuffer??=await decode(audio.blob);
 if(!dialog.open)return;
 const ac=new OfflineAudioContext(1,Math.ceil(voiceBuffer.duration*16000),16000),source=ac.createBufferSource();source.buffer=voiceBuffer;source.connect(ac.destination);source.start();const buffer=await ac.startRendering();
 if(!dialog.open)return;
 const task=new Worker('sync-worker.js',{type:'module'});syncWorker=task;
 task.onerror=e=>{if(syncWorker!==task)return;cancelSync();$('#syncState').textContent='Model belum dapat dimuat: '+(e.message||'Periksa koneksi, lalu coba lagi.')+' Anda juga bisa memasukkan timing manual.';$('#syncProgress').hidden=true;};
 task.onmessage=({data})=>{if(syncWorker!==task)return;if(data.type==='progress')$('#syncState').textContent=data.text;
 if(data.type==='error'){cancelSync();$('#syncState').textContent='Sinkronisasi belum berhasil: '+data.message;$('#syncProgress').hidden=true;$('#cancelSync').textContent='Tutup';}
 if(data.type==='done'){try{if(p!==project||p.audio!==audio||p.scenes.map(s=>s.text).join(' ')!==script)throw Error('Proyek berubah. Ulangi sinkronisasi dengan data terbaru.');p.scenes=align(p,data.result.words,audio.duration);p.alignmentReview=data.result.review;p.alignmentInfo={matched:data.result.matched,total:data.result.total,engine:'whisper-tiny-local'};changed();cancelSync();dialog.close();localMode[2]=1;render();notify(data.result.review.length+' kata memakai perkiraan. Dengarkan dan tinjau timing sebelum melanjutkan.');}catch(e){cancelSync();showError(e);$('#syncProgress').hidden=true;}}
 };
 const samples=buffer.getChannelData(0).slice();task.postMessage({audio:samples,script,duration:audio.duration},[samples.buffer]);
}
dialog.addEventListener('close',cancelSync);
function scene(){const row=p.scenes[selected];if(!row){$('#editor').innerHTML='<h1>Belum ada adegan.</h1><p>Buat storyboard di tab Ide terlebih dahulu.</p>';return;}$('#editor').innerHTML=`<h1>Animasi per kelompok</h1><p class="intro">Prompt membawa visual, timing kata, kode dunia, dan akhir scene sebelumnya. Tempel hasilnya lalu tinjau di monitor.</p><label for="chooseScene">Scene aktif</label><select id="chooseScene">${p.scenes.map((s,i)=>`<option value="${i}" ${selected===i?'selected':''}>${s.id}. ${esc(s.text.slice(0,70))}</option>`).join('')}</select><p class="scene-caption">${esc(row.text)}</p>${row.reviewReason?`<p class="status-note warning">Perlu ditinjau: ${esc(row.reviewReason)}</p>`:""}<p class="note">${esc(row.visual)} · ${seconds(row.duration)}</p><div class="row"><label for="batch">Jumlah scene</label><input id="batch" style="width:90px" type="number" min="1" max="${p.scenes.length-selected}" value="${Math.min(3,p.scenes.length-selected)}"><button id="animPrompt" class="primary">Salin prompt animasi</button><button id="pasteCode">Tempel kode AI</button></div><label for="sceneCode">Kode scene ${row.id}</label><textarea id="sceneCode" class="code" spellcheck="false" placeholder="Isi body function (s, ctx) { ... }">${esc(row.code)}</textarea><div class="row"><button id="applyCode">Simpan & tinjau scene</button><button id="downloadCode">Unduh semua kode</button><button id="repairCode">Salin prompt perbaikan</button>${row.code?'<button id="markSceneReviewed">Tandai sudah ditinjau</button>':''}</div><details><summary>Kode DUNIA bersama</summary><p class="note">Dievaluasi ulang setiap frame. Perubahan memengaruhi seluruh scene.</p><label for="worldCode">DUNIA</label><textarea id="worldCode" class="code" spellcheck="false">${esc(p.world)}</textarea><button id="applyWorld">Simpan DUNIA</button></details>`;$('#chooseScene').onchange=e=>{pause();selected=Number(e.target.value);position=0;render();};button('animPrompt',()=>promptDialog('Prompt animasi',animationPrompt(p,selected,Number($('#batch').value))));button('applyCode',()=>{const code=$('#sceneCode').value;syntax(p.world,code,row.id);invalidate(p,'Kode scene sebelumnya berubah.',selected+1);row.code=code;delete row.reviewReason;changed();position=0;localMode[3]=1;setView('monitor');render();});button('applyWorld',()=>{const world=$('#worldCode').value;for(const r of p.scenes)if(r.code)syntax(world,r.code,r.id);invalidate(p,'DUNIA berubah; tinjau kesinambungan model.');p.world=world;changed();render();});button('repairCode',()=>promptDialog('Perbaiki scene '+row.id,repairPrompt(p,selected,$('#preview-error').textContent)));button('markSceneReviewed',()=>{delete row.reviewReason;changed();render();});button('downloadCode',()=>download(new Blob([sourceOf(p)],{type:'text/javascript'}),'scenes.js'));button('pasteCode',()=>{openDialog('Tempel kode animasi','<p>Tempel satu atau beberapa scene beserta penandanya. Scene lain tetap tersimpan.</p><label for="batchCode">Kode dari AI</label><textarea id="batchCode" class="code" spellcheck="false"></textarea><div class="row"><button id="importCode" class="primary">Terapkan kode</button></div>');button('importCode',()=>{const result=parseCode($('#batchCode').value),world=result.world??p.world;for(const r of result.scenes){if(!p.scenes.some(s=>s.id===r.id))throw Error(`Scene ${r.id} tidak ada di storyboard.`);syntax(world,r.code,r.id);}if(result.world!==null)for(const r of p.scenes)if(r.code&&!result.scenes.some(x=>x.id===r.id))syntax(world,r.code,r.id);if(world!==p.world)invalidate(p,'DUNIA diganti; tinjau model.');p.world=world;const first=Math.min(...result.scenes.map(r=>p.scenes.findIndex(s=>s.id===r.id)));invalidate(p,'Scene sebelumnya diperbarui; tinjau sambungannya.',first+1);for(const r of result.scenes){const target=p.scenes.find(s=>s.id===r.id);target.code=r.code;delete target.reviewReason;}selected=first;changed();position=0;dialog.close();localMode[3]=1;setView('monitor');render();});});}
function exportPanel(){const missing=p.scenes.filter(s=>!s.code.trim()),stale=p.scenes.filter(s=>s.reviewReason);$('#editor').innerHTML=`<h1>Ekspor MP4</h1><p class="intro">Render frame demi frame, gabungkan VO dan efek suara, lalu unduh hasilnya.</p><div class="export-summary">${p.scenes.length} SCENE / ${seconds(total(p))}</div><p>${missing.length?`${missing.length} scene belum memiliki kode.`:'Semua scene memiliki kode.'} ${p.audio?'VO tersedia.':'Tanpa VO unggahan.'}</p>${p.audio&&Math.abs(p.audio.duration-total(p))>.08?'<p class="status-note warning">Durasi VO dan timeline berbeda. Sinkronkan timing sebelum ekspor.</p>':''}${stale.length?`<p class="status-note warning">${stale.length} scene perlu ditinjau karena data proyek berubah. Periksa di tab Scene.</p>`:""}<div class="two"><div><label for="resolution">Lebar video vertikal</label><select id="resolution"><option value="480">480 × 854</option><option value="720" selected>720 × 1280</option><option value="1080">1080 × 1920</option></select></div><div><label for="fps">Frame per detik</label><select id="fps"><option>24</option><option selected>30</option><option>60</option></select></div></div><p class="note">Format ${esc(p.aspect)}${p.aspect==='16:9'?', dimensi dibalik menjadi horizontal':''}. Dukungan encoder mengikuti browser Anda. Perangkat dengan memori terbatas sebaiknya mulai dari 480p.</p><div class="row"><button id="exportVideo" class="primary" ${!p.scenes.length||missing.length?'disabled':''}>Render MP4</button><button id="package" ${!p.scenes.length||missing.length?'disabled':''}>Unduh paket renderer</button><button id="subtitleDownload" ${!p.scenes.length?'disabled':''}>Unduh subtitle SRT</button></div><p class="note">Paket renderer berisi kode, audio dan program FFmpeg untuk ekspor MP4 di komputer. Jika belum ada timing kata, subtitle memakai perkiraan durasi scene.</p>`;button('exportVideo',renderExport);button('package',rendererPackage);button('subtitleDownload',()=>download(new Blob([srt(p)],{type:'text/plain'}),'subtitle.srt'));}
function dimensions(){const w=Number($('#resolution').value),h=w===480?854:w===720?1280:1920;return p.aspect==='16:9'?[h,w]:[w,h];}
function readyExport(){if(p.scenes.some(s=>s.reviewReason))throw Error('Ada scene yang perlu ditinjau. Periksa di tab Scene lalu tandai sudah ditinjau.');if(!p.scenes.length||p.scenes.some(s=>!s.code.trim()))throw Error('Lengkapi kode semua scene.');if(!sameNarration(p.narration,p.scenes.map(s=>s.text).join(' ')))throw Error('Naskah di tab Ide berubah. Perbarui storyboard sebelum ekspor.');if(p.audio&&Math.abs(p.audio.duration-total(p))>.08)throw Error('Durasi VO dan timeline belum sama. Sinkronkan atau koreksi timing di tab Suara.');for(const r of p.scenes)syntax(p.world,r.code,r.id);}
async function renderExport(){readyExport();pause();const [width,height]=dimensions(),fps=Number($('#fps').value);const configs=await support(width,height,fps);openDialog('Render video',`<p>${width} × ${height} · ${fps} fps · ${configs.video.codec.startsWith('avc')?'H.264':'VP9'} + ${configs.audio.codec==='opus'?'Opus':'AAC'} dalam MP4${configs.audio.codec==='opus'||!configs.video.codec.startsWith('avc')?' · pemutar lama mungkin tidak mendukung codec ini':''}</p><p>Jaga halaman ini tetap terbuka selama render.</p><progress id="progress" max="1" value="0"></progress><p id="progressText" role="status">Menyiapkan suara…</p><button id="cancelExport">Batalkan</button>`);exporting=true;cancelExport=false;button('cancelExport',()=>{cancelExport=true;});try{voiceBuffer=p.audio?(voiceBuffer??await decode(p.audio.blob)):null;musicBuffer=p.music?(musicBuffer??await decode(p.music.blob)):null;const result=await exportVideo(p,canvas,{width,height,fps,draw,voice:voiceBuffer,music:musicBuffer,cancelled:()=>cancelExport,progress:(v,text)=>{$('#progress').value=v;$('#progressText').textContent=text;}});download(result.blob,'ruang-adegan.mp4');$('#progressText').textContent=`Selesai. ${result.frames} frame; ${(result.blob.size/1048576).toFixed(1)} MB.`;$('#cancelExport').textContent='Unduh lagi';$('#cancelExport').onclick=()=>download(result.blob,'ruang-adegan.mp4');if(cloud.status()){const b=document.createElement('button');b.textContent='Simpan MP4 ke cloud';$('#dialog-body').append(b);b.onclick=async()=>{b.disabled=true;try{await cloud.saveMp4(p,result.blob);b.textContent='MP4 tersimpan di cloud';}catch(e){b.disabled=false;showError(e);}};}}finally{exporting=false;position=0;preview();}}
async function rendererPackage(){readyExport();const [width,height]=dimensions(),fps=Number($('#fps').value);notify('Menyiapkan paket renderer…');const response=await fetch('renderer.zip');if(!response.ok)throw Error('Paket renderer tidak ditemukan.');const files=unzipSync(new Uint8Array(await response.arrayBuffer())),root=Object.keys(files).find(k=>k.endsWith('PANDUAN.md'))?.replace(/PANDUAN.md$/,'')||'';const audio={sfx:p.sfx};for(const [key,label]of[['audio','voiceover'],['music','music']])if(p[key]){const ext=p[key].name.split('.').at(-1).replace(/[^a-z0-9]/gi,'')||'wav',filename=label+'.'+ext;files[root+'proyek/'+filename]=new Uint8Array(await p[key].blob.arrayBuffer());audio[label]=filename;}audio.musicGain=p.volume;const manifest={source:'scenes.js',width,height,logicalWidth:p.aspect==='16:9'?1280:720,logicalHeight:p.aspect==='16:9'?720:1280,fps,captionY:p.aspect==='16:9'?610:842,background:p.background,scenes:p.scenes.map(r=>({id:r.id,duration:r.duration,theme:r.theme,caption:p.subtitle?r.text:'',words:r.cues.map(c=>({text:c.word,start:c.start}))})),audio};manifest.assets=[];for(const a of p.assets||[]){const ext=a.type==='image/png'?'png':a.type==='image/jpeg'?'jpg':'webp',path='assets/'+a.id+'.'+ext;files[root+'proyek/'+path]=new Uint8Array(await a.blob.arrayBuffer());manifest.assets.push({id:a.id,path});}files[root+'proyek/scenes.js']=strToU8(sourceOf(p));files[root+'proyek/project.json']=strToU8(JSON.stringify(manifest,null,2));files[root+'MULAI.txt']=strToU8('Pasang Node.js dan FFmpeg. Buka terminal di folder ini.\nJalankan: npm install @napi-rs/canvas\nLalu: node scripts/render.cjs proyek/project.json --out hasil.mp4\n\nBaca PANDUAN.md. Kode animasi dari AI harus ditinjau sebelum dijalankan.\n');download(new Blob([zipSync(files,{level:6})],{type:'application/zip'}),'ruang-adegan-renderer.zip');notify('Paket renderer siap.');}
async function backup(){const out={...p,assets:await Promise.all((p.assets||[]).map(async a=>({...a,blob:undefined,data:await base64(a.blob)})))};for(const k of ['audio','music'])if(p[k])out[k]={...p[k],blob:undefined,data:await base64(p[k].blob)};download(new Blob([JSON.stringify(out)],{type:'application/json'}),'ruang-adegan-proyek.json');}
async function filesDialog(){await persist();const projects=(await storage.list()).sort((a,b)=>b.updated-a.updated);openDialog('Proyek & berkas',`<div class="row"><button id="newProject" class="primary">Proyek baru</button><button id="backup">Unduh cadangan</button></div><label for="importProject">Buka cadangan proyek JSON</label><input id="importProject" type="file" accept=".json,application/json"><div class="prompt-actions"><p><strong>Penyimpanan cloud</strong><br>${cloud.status()?esc(cloud.status().email):"Belum terhubung. Proyek saat ini disimpan di perangkat."}</p><button id="cloudSettings">${cloud.status()?"Buka proyek cloud":"Hubungkan Supabase"}</button></div><div class="row"><button id="persistStorage">Lindungi penyimpanan</button><button id="storageUsage">Lihat kapasitas</button></div><p id="storageState" role="status"></p><h3>Di perangkat ini</h3>${projects.map(x=>`<div class="project-item"><div><strong>${esc(x.title)}</strong><small>${x.scenes.length} scene · ${new Date(x.updated).toLocaleString('id-ID')}</small></div><button data-project="${esc(x.id)}">Buka</button></div>`).join('')}`);button('persistStorage',async()=>{$('#storageState').textContent=await navigator.storage?.persist?.()?'Penyimpanan persisten diizinkan. Tetap unduh cadangan.':'Browser belum memberi penyimpanan persisten. Gunakan cadangan proyek.';});button('storageUsage',async()=>{const e=await navigator.storage?.estimate?.();$('#storageState').textContent=e?`Terpakai ${(e.usage/1048576).toFixed(1)} MB dari kuota ${(e.quota/1048576).toFixed(0)} MB.`:'Informasi kapasitas tidak tersedia.';});button('cloudSettings',cloudDialog);button('newProject',async()=>{pause();await persist();p=fresh();p.assets=[];selected=0;position=0;voiceBuffer=musicBuffer=null;tab=0;await persist();dialog.close();render();});button('backup',backup);$('#importProject').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const next=validateProject(JSON.parse(await f.text()));for(const k of ['audio','music'])if(next[k]){if(!next[k].data)throw Error('Data audio cadangan tidak lengkap.');next[k].blob=unbase64(next[k].data,next[k].type);delete next[k].data;}for(const a of next.assets||[]){if(!a.data)throw Error('Cadangan aset tidak lengkap.');a.blob=unbase64(a.data,a.type);delete a.data;}next.id=crypto.randomUUID();delete next.cloudRevision;await switchProject(next);dialog.close();}catch(err){showError(err);}};document.querySelectorAll('[data-project]').forEach(b=>b.onclick=async()=>{await switchProject(projects.find(x=>x.id===b.dataset.project));dialog.close();});}
async function switchProject(next){pause();await persist();stopWorker();p=next;p.assets??=[];p.styleId??=styleOf(p).id;selected=0;position=0;voiceBuffer=musicBuffer=null;await persist();render();}
button('files',filesDialog);$('#projectTitle').onchange=e=>{p.title=e.target.value.trim()||'Proyek tanpa judul';changed();};button('demo',async()=>{const r=await fetch('demo.json');if(!r.ok)throw Error('Contoh belum tersedia.');const demo=await r.json();demo.id=crypto.randomUUID();await switchProject(demo);tab=3;render();notify('Contoh dibuka sebagai proyek terpisah.');});$('.brand').onclick=e=>{e.preventDefault();pause();tab=0;render();};
window.addEventListener('pagehide',()=>{pause();persist();});
try{const projects=await storage.list(),id=localStorage.getItem('ruang-active');p=projects.find(x=>x.id===id)||projects.sort((a,b)=>b.updated-a.updated)[0]||fresh();}catch{notify('Penyimpanan perangkat tidak tersedia. Gunakan cadangan JSON.');}render();

function setView(view){document.body.dataset.view=view;window.scrollTo(0,0);$('#editorView').setAttribute('aria-pressed',String(view==='editor'));$('#monitorView').setAttribute('aria-pressed',String(view==='monitor'));if(view==='monitor')preview();}
button('editorView',()=>setView('editor'));button('monitorView',()=>setView('monitor'));
button('repairPreview',()=>promptDialog('Perbaiki scene',repairPrompt(p,selected,$('#preview-error').textContent)));

async function cloudDialog(){
 const account=cloud.status();
 if(!account){openDialog('Akun REKA Studio','<p>Masuk untuk menyimpan proyek dan audio di cloud. Proyek lokal tetap dapat digunakan tanpa akun.</p><label for="cloudEmail">Email</label><input id="cloudEmail" type="email" autocomplete="username" placeholder="Alamat email Anda"><label for="cloudPassword">Kata sandi</label><input id="cloudPassword" type="password" autocomplete="current-password" placeholder="Kata sandi akun"><p class="note">Akun ini terpisah dari akun ChatGPT. Sesi hanya aktif selama halaman terbuka.</p><div class="row"><button id="cloudLogin" class="primary">Masuk</button><button id="cloudSignup">Buat akun</button></div><p id="cloudState" role="status"></p>');
 const credentials=()=>{const email=$('#cloudEmail').value.trim(),password=$('#cloudPassword').value;if(!$('#cloudEmail').checkValidity()||!email||!password)throw Error('Isi email yang valid dan kata sandi.');return {email,password};};
 button('cloudLogin',async()=>{const {email,password}=credentials(),b=$('#cloudLogin');b.disabled=true;try{$('#cloudState').textContent='Menghubungkan akun…';await cloud.login(email,password);await cloudDialog();}finally{b.disabled=false;}});
 button('cloudSignup',async()=>{const {email,password}=credentials();if(password.length<8)throw Error('Gunakan kata sandi minimal 8 karakter.');const b=$('#cloudSignup');b.disabled=true;try{const r=await cloud.signup(email,password);if(r.signedIn)await cloudDialog();else $('#cloudState').textContent='Periksa email untuk konfirmasi akun, lalu kembali dan masuk.';}finally{b.disabled=false;}});return;}
 openDialog('Proyek cloud',`<p>Terhubung sebagai <strong>${esc(account.email)}</strong>.</p><p class="note">Simpan ke cloud secara manual setelah mengedit. Penyimpanan otomatis tetap berada di perangkat ini.</p><div class="row"><button id="cloudSave" class="primary">Simpan proyek ini & audio</button><button id="cloudLogout">Keluar</button></div><p id="cloudState" role="status">Memuat proyek…</p><div id="cloudProjects"></div>`);
 button('cloudLogout',async()=>{await cloud.logout();await filesDialog();});
 button('cloudSave',async()=>{const b=$('#cloudSave');b.disabled=true;try{$('#cloudState').textContent='Menyimpan naskah, kode, dan audio…';p.cloudRevision=await cloud.saveProject(p);await persist();$('#cloudState').textContent='Proyek dan audio tersimpan di cloud.';await listCloud();}finally{b.disabled=false;}});
 async function listCloud(){const rows=await cloud.projects();$('#cloudProjects').innerHTML=rows.length?rows.map(r=>`<div class="project-item"><div><strong>${esc(r.title)}</strong><small>${new Date(r.updated_at).toLocaleString('id-ID')}</small></div><button data-cloud-id="${esc(r.id)}">Buka</button></div>`).join(''):'<p>Belum ada proyek di cloud. Simpan proyek pertama Anda dengan tombol di atas.</p>';document.querySelectorAll('[data-cloud-id]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{$('#cloudState').textContent='Mengunduh proyek dan audio…';const next=validateProject(await cloud.openProject(b.dataset.cloudId));await switchProject(next);dialog.close();notify('Proyek cloud dibuka. Perubahan selanjutnya tersimpan di perangkat hingga Anda menyimpan ke cloud lagi.');}catch(e){b.disabled=false;showError(e);}});}
 try{await listCloud();$('#cloudState').textContent='Daftar proyek diperbarui.';}catch(e){$('#cloudState').textContent='Tidak dapat membaca tabel video_projects. Jalankan pengaturan SQL terlebih dahulu.';throw e;}
}

function mountGallery(){const host=document.createElement('section');host.className='style-gallery';host.innerHTML=`<div class="section-heading"><h2>Gaya video</h2><span>${esc(styleOf(p).name)}</span></div><div class="style-grid">${styles.map(v=>`<article class="style-option ${styleOf(p).id===v.id?'chosen':''}"><img src="assets/styles/${v.id}.webp" width="900" height="506" loading="lazy" alt="Referensi visual ${esc(v.name)}"><div><h3>${esc(v.name)}</h3><p>${esc(v.description)}</p><div class="row"><button data-pick-style="${v.id}" aria-pressed="${styleOf(p).id===v.id}">${styleOf(p).id===v.id?'Dipakai':'Pilih gaya'}</button><button data-demo-style="${v.id}">Buka contoh</button></div></div></article>`).join('')}</div><p class="note">Foto referensi membantu memilih arah visual. Hasil video mengikuti kode scene Anda. Referensi: Bang Motion dan video yang Anda berikan.</p><label class="row"><input id="characters" type="checkbox" ${p.characters?'checked':''}> Izinkan karakter bila sesuai isi</label>`;const fold=document.createElement('details');fold.className='style-picker';fold.innerHTML='<summary>Ganti gaya · '+esc(styleOf(p).name)+'</summary>';fold.append(host);$('#wordCount').after(fold);host.querySelectorAll('[data-pick-style]').forEach(b=>b.onclick=()=>{pause();const v=styles.find(x=>x.id===b.dataset.pickStyle);p.styleId=v.id;p.style=v.name;invalidate(p,'Gaya video berubah; tinjau storyboard dan kode.');changed();render();});host.querySelectorAll('[data-demo-style]').forEach(b=>b.onclick=async()=>{await switchProject(demoProject(b.dataset.demoStyle));tab=3;localMode[3]=1;setView('monitor');render();notify('Contoh dibuka sebagai proyek terpisah.');});$('#characters').onchange=e=>{p.characters=e.target.checked;invalidate(p,'Aturan karakter berubah.');changed();};}
function mountQueue(){if(!p.scenes.length)return;const size=Math.max(1,Math.min(20,Number(p.batchSize)||3)),host=document.createElement('section');host.className='batch-queue';host.innerHTML=`<div class="section-heading"><h2>Kelompok scene</h2><label for="queueBatch">Scene per kirim <input id="queueBatch" type="number" min="1" max="20" value="${size}"></label></div>${Array.from({length:Math.ceil(p.scenes.length/size)},(_,i)=>{const rows=p.scenes.slice(i*size,(i+1)*size),ready=rows.filter(r=>r.code).length;return `<button data-batch-start="${i*size}" class="queue-item ${selected>=i*size&&selected<(i+1)*size?'current':''}"><strong>Scene ${rows[0].id}–${rows.at(-1).id}</strong><span>${rows.some(r=>r.reviewReason)?'Perlu ditinjau':ready===rows.length?'Kode tersedia':ready?'Sebagian kode tersedia':'Belum ada kode'}</span><b>${ready}/${rows.length}</b></button>`;}).join('')}`;$('#editor').append(host);$('#queueBatch').onchange=e=>{const n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>20){notify('Isi jumlah 1–20.');render();return;}p.batchSize=n;changed();render();};host.querySelectorAll('[data-batch-start]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.batchStart);position=0;render();$('#batch').value=String(Math.min(size,p.scenes.length-selected));});}
function mountAssets(){const host=document.createElement('details');host.className='asset-panel';host.innerHTML=`<summary>Aset proyek <span>${(p.assets||[]).length} gambar</span></summary><p class="note">Unggah PNG, JPEG atau WebP. Gunakan ID yang sama di kode: s.photo("gambar_1",x,y,w,h). Aset ikut cadangan proyek.</p><label for="assetFile">Tambah gambar</label><input id="assetFile" type="file" accept="image/png,image/jpeg,image/webp"><div class="asset-list">${(p.assets||[]).map((a,i)=>`<article><strong>${esc(a.id)}</strong><small>${esc(a.name)}</small><label for="asset-credit-${i}">Sumber / kredit</label><input id="asset-credit-${i}" data-credit="${i}" value="${esc(a.credit||'')}"><button data-delete-asset="${i}">Hapus aset</button></article>`).join('')}</div>`;$('#editor').append(host);$('#assetFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>12*1048576)throw Error('Gunakan PNG/JPEG/WebP maksimal 12 MB.');const image=await createImageBitmap(file);if(image.width*image.height>20000000){image.close();throw Error('Resolusi gambar terlalu besar; kecilkan hingga maksimal 20 megapiksel.');}image.close();p.assets??=[];const n=1+Math.max(0,...p.assets.map(a=>Number(a.id.replace('gambar_',''))||0));p.assets.push({id:'gambar_'+n,name:file.name,type:file.type,blob:file,credit:''});changed();render();}catch(e){showError(e);}};host.querySelectorAll('[data-credit]').forEach(el=>el.onchange=()=>{p.assets[Number(el.dataset.credit)].credit=el.value;changed();});host.querySelectorAll('[data-delete-asset]').forEach(b=>b.onclick=()=>{p.assets.splice(Number(b.dataset.deleteAsset),1);invalidate(p,'Aset dihapus; periksa kode yang menggunakannya.');changed();render();});}

button('headerExport',()=>{pause();tab=4;setView('editor');render();});
button('viewPrompt',viewPrompt);

function mountFlowEnhancements(){
 if(tab===2&&localMode[2]===0)mountTts();
 if(tab===2&&localMode[2]===1&&p.audio){const next=document.createElement('button');next.className='primary';next.textContent='Lanjut ke animasi';next.onclick=()=>{tab=3;localMode[3]=0;setView('editor');render();};$('#editor').append(next);}
 if(tab===3&&localMode[3]===1){const nextIndex=p.scenes.findIndex(s=>!s.code);if(nextIndex>=0){const next=document.createElement('button');next.textContent='Kerjakan kelompok berikutnya';next.onclick=()=>{selected=nextIndex;localMode[3]=0;setView('editor');render();};$('#editor').append(next);}}
 if(tab===1&&localMode[1]===1){document.querySelectorAll('.scene-row').forEach(row=>{const host=row.children[1],text=host.firstElementChild,details=document.createElement('details');details.className='scene-fields';details.innerHTML='<summary>Arahan visual & kamera</summary>';while(text.nextSibling)details.append(text.nextSibling);host.append(details);});}
 if(tab===0){const paste=$('#pasteStory');if(paste){const original=paste.onclick;paste.onclick=async()=>{await original();const input=$('#storyInput');if(!input)return;input.oninput=()=>{try{const data=storyboardData(input.value,p.narration);$('#storyCheck').textContent=data.scenes.length+' scene valid. Narasi cocok. Siap diterapkan.';$('#applyStory').disabled=false;}catch(e){$('#applyStory').disabled=true;$('#storyCheck').textContent=input.value.trim()?e.message:'';}};};}}
}

function mountTts(){
 const section=document.createElement('details');section.className='tts-panel';section.innerHTML='<summary>Buat voiceover di sini · opsional</summary><p class="note">Hanya fitur ini yang membutuhkan API key Gemini. Narasi dikirim ke Google saat Anda menekan Buat voiceover; biaya mengikuti akun API Anda. Key tidak disimpan dalam proyek.</p><label for="ttsKey">API key Gemini</label><input id="ttsKey" type="password" autocomplete="off" placeholder="Masukkan API key untuk membuat suara"><label for="ttsVoice">Pilihan suara</label><select id="ttsVoice"><option>Kore</option><option>Puck</option><option>Charon</option><option>Fenrir</option><option>Aoede</option></select><label for="ttsStyle">Arahan bicara</label><textarea id="ttsStyle" placeholder="Jelaskan tempo dan gaya bicara yang Anda inginkan"></textarea><button id="generateVoice" class="primary">Buat voiceover dari narasi</button><p id="ttsState" role="status"></p>';$('#editor').append(section);
 button('generateVoice',async()=>{const key=$('#ttsKey').value.trim();if(!key)throw Error('Isi API key Gemini untuk membuat suara.');if(!p.narration.trim())throw Error('Isi narasi terlebih dahulu.');const b=$('#generateVoice'),project=p,script=p.narration;b.disabled=true;$('#ttsState').textContent='Membuat voiceover…';try{const response=await fetch('https://generativelanguage.googleapis.com/v1beta/interactions',{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':key},signal:AbortSignal.timeout(180000),body:JSON.stringify({model:'gemini-3.8-flash-tts',input:[{type:'user_input',content:[{type:'text',text:script,annotations:[{type:'speech_metadata',style:$('#ttsStyle').value.trim()||'Bahasa Indonesia, jelas dan natural.'}]}]}],response_format:{type:'audio'},generation_config:{speech_config:[{voice:$('#ttsVoice').value}]}})});const result=await response.json();if(!response.ok)throw Error(result.error?.message||'Pembuatan suara gagal.');const audio=result.steps?.filter(s=>s.type==='model_output').flatMap(s=>s.content||[]).filter(c=>c.type==='audio').at(-1);if(!audio?.data)throw Error('Layanan belum mengembalikan audio.');if(p!==project||p.narration!==script)throw Error('Narasi berubah selama pembuatan suara. Ulangi dengan narasi terbaru.');const blob=unbase64(audio.data,'audio/wav');await uploadAudio(new File([blob],'voiceover-reka.wav',{type:'audio/wav'}),'audio');}catch(e){if($('#ttsState'))$('#ttsState').textContent=e.message;else showError(e);}finally{b.disabled=false;}});
}

function configureVoicePane(pane){
 if(pane===0){for(const id of ['sync','alignPrompt','timing']){const e=document.getElementById(id);if(e)e.hidden=true;}const b=document.createElement('button');b.textContent='Buka Sinkron';b.className='primary';b.onclick=()=>{localMode[2]=1;render();};$('#editor').append(b);}
 else{for(const id of ['voiceFile','musicFile','removeVoice','removeMusic','musicVolume','subtitles','sfx']){const e=document.getElementById(id);if(e){const label=$('#editor label[for="'+id+'"]');if(label)label.remove();if(e.parentElement.tagName==='LABEL')e.parentElement.remove();else e.remove();}}if(!p.audio){$('#editor').insertAdjacentHTML('beforeend','<p class="status-note warning">Unggah VO di Atur terlebih dahulu untuk menyinkronkan subtitle.</p>');}}
}
